'use client';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { Brand } from '../lib/brands';
import { cx } from '../lib/cx';
import { useCopied } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Swap, Tip } from '../lib/motion';
import '../designme.css';
import './meeting-card.css';

export interface MeetingCardProps {
  /** Like "Meeting with Product team" */
  title: string;
  /** When it starts, 24-hour "HH:MM", like "10:30" */
  start: string;
  /** When it ends, like "12:00" */
  end: string;
  /** The time now, like "10:00". The now line sits there, and the countdown and the live state follow it */
  now: string;
  /** Where the track starts. Defaults to half an hour before `start` */
  from?: string;
  /** Where the track ends. Defaults to half an hour after `end` */
  to?: string;
  /** The label inside the meeting's block. Defaults to its length, like "90 min" */
  length?: string;
  /** The line over the title. Defaults to the countdown: "In 30 minutes", "Starting now", "Ended" */
  status?: string;
  /** The call's service, for the join line. Defaults to "Google Meet" */
  provider?: string;
  /** The service's mark. Defaults to the Google Meet mark */
  mark?: ReactNode;
  /** The link shown and copied, like "meet.google.com/nax-wqkf-stu" */
  link: string;
  /** Where joining goes. Defaults to the link over https */
  href?: string;
  /** Called on join. Left out, the link opens in a new tab */
  onJoin?: () => void;
  onCopy?: (url: string) => void;
  /** The copy button's tooltip and name. Defaults to "Copy link" */
  copyLabel?: string;
  /** The tooltip after copying. Defaults to "Copied" */
  copiedLabel?: string;
  className?: string;
}

const mins = (t: string) => { const [h, m] = t.split(':').map(Number); return h * 60 + (m || 0); };
const clock = (m: number) => `${Math.floor(m / 60)}:${String(m % 60).padStart(2, '0')}`;

/** The next meeting: a countdown, a time track with the meeting on it and a now line creeping toward it, and the call's
    join link with a copy button. At the start time the meeting turns live. */
export function MeetingCard({ title, start, end, now, from, to, length, status, provider = 'Google Meet', mark, link, href, onJoin, onCopy,
  copyLabel = 'Copy link', copiedLabel = 'Copied', className }: MeetingCardProps) {
  const a = mins(start), b = mins(end), t = mins(now);
  const lo = from ? mins(from) : a - 30, hi = to ? mins(to) : b + 30, span = Math.max(1, hi - lo);
  const pc = (m: number) => Math.min(100, Math.max(0, (m - lo) / span * 100));
  const left = a - t, live = t >= a && t < b;
  const text = status ?? (left > 0 ? `In ${left} minute${left === 1 ? '' : 's'}` : t < b ? 'Starting now' : 'Ended');
  // ticks every 15 minutes, the hours a step taller
  const ticks: number[] = [];
  for (let m = Math.ceil(lo / 15) * 15; m <= hi; m += 15) ticks.push(m);
  const url = href ?? 'https://' + link.replace(/^https?:\/\//, '');
  const [copied, copy] = useCopied();
  // joining says so for a moment, the way the site's demo does
  const join = `Join on ${provider}`;
  const [label, setLabel] = useState(join);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  useEffect(() => setLabel(join), [join]);
  const go = () => {
    setLabel(`Opening ${provider}`); clearTimeout(timer.current); timer.current = setTimeout(() => setLabel(join), 1600);
    if (onJoin) onJoin(); else window.open(url, '_blank', 'noopener');
  };

  return (
    <div data-dm="" className={cx('dm-mtx dm-panel', live && 'dm-live', className)}>
      <div className="dm-mtx-top">
        <div className="dm-mtx-when"><span className="dm-mtx-dot" /><span className="dm-mtx-in dm-num">{text}</span></div>
        <b className="dm-mtx-t">{title}</b>
        <div className="dm-mtx-track" role="img" aria-label={`Now ${clock(t)}. The meeting runs ${start} to ${end}`}>
          <span className="dm-mtx-ticks">{ticks.map(m => <i key={m} className={m % 60 ? undefined : 'dm-h'} style={{ left: pc(m) + '%' }} />)}</span>
          <span className="dm-mtx-blk" style={{ left: pc(a) + '%', width: pc(b) - pc(a) + '%' }}><span className="dm-num">{length ?? `${b - a} min`}</span></span>
          <span className="dm-mtx-now" style={{ ['--dm-p' as string]: pc(t) + '%' }}><i /></span>
        </div>
        <div className="dm-mtx-axis dm-num" aria-hidden="true">
          <span className="dm-a">{from ?? clock(lo)}</span>
          <span style={{ left: pc(a) + '%' }}>{start}</span>
          <span style={{ left: pc(b) + '%' }}>{end}</span>
          <span className="dm-z">{to ?? clock(hi)}</span>
        </div>
      </div>
      <div className="dm-mtx-join">
        <button type="button" className="dm-mtx-go" onClick={go}>
          <span className="dm-mtx-mk">{mark ?? <Brand name="meet" />}</span>
          <span className="dm-mtx-gt"><b><Swap>{label}</Swap></b><span className="dm-mtx-url">{link}</span></span>
          <span className="dm-mtx-ar"><Icon name="right" /></span>
        </button>
        <Tip label={copied ? copiedLabel : copyLabel} open={copied || undefined}>
          <button type="button" className={cx('dm-ib dm-mtx-cp', copied && 'dm-copied')} aria-label={copyLabel} onClick={() => { copy(url); onCopy?.(url); }}>
            <Icon name={copied ? 'check' : 'copy'} />
          </button>
        </Tip>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Meeting card ---------- */
/* the next meeting: a countdown, its place on a time track (10:00 to 12:30, ticks every 15 minutes) with the now line creeping
   toward it, and the call's join link. The meeting is the accent tint, the now line the accent mark; at the start time the
   block turns live (a ring round it) and the dot beside the countdown pulses. Every state is the same height */
.dm-mtx{width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-2);display:flex;flex-direction:column;gap:var(--dm-s-1)}
.dm-mtx-top{display:flex;flex-direction:column;padding:var(--dm-s-3) var(--dm-s-4) var(--dm-s-3);border-radius:calc(12px * var(--dm-rk));background:var(--dm-row);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* Blueprint's box is flat, a hairline on the panel: its green now line keeps 3:1 on white, not on the row grey */
:root:not([data-style="soft"]) .dm-mtx-top:not(:where([data-style="soft"],[data-style="soft"] *)){background:var(--dm-surface)}
.dm-mtx-when{display:flex;align-items:center;gap:6px;font-size:12px;font-weight:500;color:var(--dm-fg2)}
.dm-mtx-dot{width:6px;height:6px;border-radius:50%;background:var(--dm-bad-mark);flex:none}
.dm-mtx.dm-live .dm-mtx-dot{animation:dm-mtxlive 1.6s ease-in-out infinite}
@keyframes dm-mtxlive{50%{opacity:.35}}
.dm-mtx-t{font-size:14px;font-weight:500;margin-top:4px}
/* the baseline under the ticks is drawn as the track's background */
.dm-mtx-track{position:relative;height:38px;margin-top:var(--dm-s-4);--dm-bl:color-mix(in srgb,var(--dm-rail) 70%,transparent);background:linear-gradient(var(--dm-bl),var(--dm-bl)) left bottom/100% 1px no-repeat}
.dm-mtx-ticks i{position:absolute;bottom:0;width:1px;height:5px;margin-left:-.5px;background:var(--dm-rail)}
.dm-mtx-ticks i.dm-h{height:9px;background:var(--dm-faint)}
.dm-mtx-ticks i:first-child{margin-left:0}.dm-mtx-ticks i:last-child{margin-left:-1px}
.dm-mtx-blk{position:absolute;top:2px;bottom:13px;display:flex;align-items:center;padding:0 var(--dm-s-2);border-radius:calc(6px * var(--dm-rk));background:var(--dm-accent-bg);box-shadow:inset 0 0 0 1px transparent;font-size:12px;font-weight:500;color:var(--dm-accent-fg);transition:background var(--dm-t),box-shadow var(--dm-t)}
/* live: a ring in the accent mark round the same tint, so its label keeps its contrast */
.dm-mtx.dm-live .dm-mtx-blk{box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark)}
.dm-mtx-now{position:absolute;top:-4px;bottom:0;left:var(--dm-p,0%);width:2px;margin-left:-1px;border-radius:1px;background:var(--dm-accent-mark);transition:left .3s linear;z-index:1}
.dm-mtx-now i{position:absolute;top:-4px;left:50%;width:8px;height:8px;border-radius:1.5px;background:var(--dm-accent-mark);transform:translateX(-50%) rotate(45deg)}
.dm-mtx-axis{position:relative;height:16px;margin-top:6px;font-size:11.5px;color:var(--dm-muted)}
.dm-mtx-axis span{position:absolute;top:0;transform:translateX(-50%)}
.dm-mtx-axis .dm-a{left:0;transform:none}.dm-mtx-axis .dm-z{right:0;transform:none}
.dm-mtx-join{display:flex;align-items:center;gap:var(--dm-s-1);padding:0 var(--dm-s-1) 0 0}
.dm-mtx-go{flex:1;min-width:0;display:flex;align-items:center;gap:10px;padding:var(--dm-s-2);border-radius:calc(10px * var(--dm-rk));text-align:left;transition:background var(--dm-t-fast)}
.dm-mtx-go.dm-hv{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-mtx-go:hover{background:var(--dm-row)}}
.dm-mtx-mk{width:32px;height:32px;flex:none;display:grid;place-items:center;border-radius:calc(8px * var(--dm-rk));background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 70%,transparent)}
.dm-mtx-mk .dm-brand{width:19px;height:16px}
.dm-mtx-gt{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-mtx-gt b{font-size:13px;font-weight:500}
.dm-mtx-url{font-size:12px;color:var(--dm-muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-mtx-ar{color:var(--dm-muted);display:grid;transition:transform var(--dm-t-fast),color var(--dm-t-fast)}
.dm-mtx-go.dm-hv .dm-mtx-ar{color:var(--dm-fg);transform:translateX(2px)}
@media (hover:hover) and (pointer:fine){.dm-mtx-go:hover .dm-mtx-ar{color:var(--dm-fg);transform:translateX(2px)}}
@media (prefers-reduced-motion:reduce){.dm-mtx.dm-live .dm-mtx-dot{animation:none}.dm-mtx-now{transition:none}}

